# --- random generation ---------------------------------------------------


def _rnorm(rng, n, mean=0.0, sd=1.0):
    n = _draw_count(n)
    return rng._draw('rnorm', _uf.rnorm, (_recycle(mean, n, 'mean'), _recycle(sd, n, 'sd'),))


def _runif(rng, n, min=0.0, max=1.0):
    n = _draw_count(n)
    return rng._draw('runif', _uf.runif, (_recycle(min, n, 'min'), _recycle(max, n, 'max'),))


def _rgamma(rng, n, shape, rate=None, scale=None):
    n = _draw_count(n)
    scale = _resolve_rate_scale(rate, scale, 'rgamma')
    return rng._draw('rgamma', _uf.rgamma, (_recycle(shape, n, 'shape'), _recycle(scale, n, 'scale'),))


def _rbeta(rng, n, shape1, shape2, ncp=None):
    n = _draw_count(n)
    if ncp is None:
        return rng._draw('rbeta', _uf.rbeta, (_recycle(shape1, n, 'shape1'), _recycle(shape2, n, 'shape2'),))
    with _rng_lock:  # composed draw is atomic w.r.t. other threads
        X = _rchisq(rng, n, 2.0 * _np.asarray(shape1, dtype=float), ncp=ncp)
        return X / (X + _rchisq(rng, n, 2.0 * _np.asarray(shape2, dtype=float)))


def _rlnorm(rng, n, meanlog=0.0, sdlog=1.0):
    n = _draw_count(n)
    return rng._draw('rlnorm', _uf.rlnorm, (_recycle(meanlog, n, 'meanlog'), _recycle(sdlog, n, 'sdlog'),))


def _rchisq(rng, n, df, ncp=None):
    n = _draw_count(n)
    if ncp is None:
        return rng._draw('rchisq', _uf.rchisq, (_recycle(df, n, 'df'),))
    return rng._draw('rchisq', _uf.rnchisq, (_recycle(df, n, 'df'), _recycle(ncp, n, 'ncp'),))


def _rf(rng, n, df1, df2, ncp=None):
    n = _draw_count(n)
    if ncp is None:
        return rng._draw('rf', _uf.rf, (_recycle(df1, n, 'df1'), _recycle(df2, n, 'df2'),))
    with _rng_lock:  # composed draw is atomic w.r.t. other threads
        df1 = _recycle(df1, n, 'df1')
        df2 = _recycle(df2, n, 'df2')
        return (_rchisq(rng, n, df1, ncp=ncp) / df1) / (_rchisq(rng, n, df2) / df2)


def _rt(rng, n, df, ncp=None):
    n = _draw_count(n)
    if ncp is None:
        return rng._draw('rt', _uf.rt, (_recycle(df, n, 'df'),))
    with _rng_lock:  # composed draw is atomic w.r.t. other threads
        df = _recycle(df, n, 'df')
        return _rnorm(rng, n, ncp, 1.0) / _np.sqrt(_rchisq(rng, n, df) / df)


def _rbinom(rng, n, size, prob):
    n = _draw_count(n)
    return rng._draw('rbinom', _uf.rbinom, (_recycle(size, n, 'size'), _recycle(prob, n, 'prob'),))


def _rcauchy(rng, n, location=0.0, scale=1.0):
    n = _draw_count(n)
    return rng._draw('rcauchy', _uf.rcauchy, (_recycle(location, n, 'location'), _recycle(scale, n, 'scale'),))


def _rexp(rng, n, rate=1.0):
    n = _draw_count(n)
    rate = _inv(rate)
    return rng._draw('rexp', _uf.rexp, (_recycle(rate, n, 'rate'),))


def _rgeom(rng, n, prob):
    n = _draw_count(n)
    return rng._draw('rgeom', _uf.rgeom, (_recycle(prob, n, 'prob'),))


def _rhyper(rng, nn, m, n, k):
    nn = _draw_count(nn)
    return rng._draw('rhyper', _uf.rhyper, (_recycle(m, nn, 'm'), _recycle(n, nn, 'n'), _recycle(k, nn, 'k'),))


def _rnbinom(rng, n, size, prob=None, mu=None):
    n = _draw_count(n)
    if _resolve_prob_mu(prob, mu, 'rnbinom'):
        return rng._draw('rnbinom', _uf.rnbinom_mu, (_recycle(size, n, 'size'), _recycle(mu, n, 'mu'),))
    return rng._draw('rnbinom', _uf.rnbinom, (_recycle(size, n, 'size'), _recycle(prob, n, 'prob'),))


def _rpois(rng, n, lambda_):
    n = _draw_count(n)
    return rng._draw('rpois', _uf.rpois, (_recycle(lambda_, n, 'lambda_'),))


def _rweibull(rng, n, shape, scale=1.0):
    n = _draw_count(n)
    return rng._draw('rweibull', _uf.rweibull, (_recycle(shape, n, 'shape'), _recycle(scale, n, 'scale'),))


def _rlogis(rng, n, location=0.0, scale=1.0):
    n = _draw_count(n)
    return rng._draw('rlogis', _uf.rlogis, (_recycle(location, n, 'location'), _recycle(scale, n, 'scale'),))


def _rwilcox(rng, nn, m, n):
    nn = _draw_count(nn)
    return rng._draw('rwilcox', _uf.rwilcox, (_recycle(m, nn, 'm'), _recycle(n, nn, 'n'),))


def _rsignrank(rng, nn, n):
    nn = _draw_count(nn)
    return rng._draw('rsignrank', _uf.rsignrank, (_recycle(n, nn, 'n'),))


class RNG(_RNGBase):
    """An independent random-number stream with one method per ``r*`` function.

    ``RNG(i1, i2)`` holds the two 32-bit words of Rmath's Marsaglia-MultiCarry
    state. Each draw installs this state into the C library under a process-wide
    lock, runs the whole vectorised draw, and saves the state back, so streams are
    independent and thread-safe.

    Draws do **not** reproduce R's ``set.seed()`` (R uses Mersenne-Twister); only
    the sampling algorithms are R's.
    """

    __slots__ = ()

    def rnorm(self, n, mean=0.0, sd=1.0):
        """Random generation for the normal distribution on this stream; see :func:`accudist.rnorm`."""
        return _rnorm(self, n, mean, sd)

    def runif(self, n, min=0.0, max=1.0):
        """Random generation for the uniform distribution on this stream; see :func:`accudist.runif`."""
        return _runif(self, n, min, max)

    def rgamma(self, n, shape, rate=None, scale=None):
        """Random generation for the gamma distribution on this stream; see :func:`accudist.rgamma`."""
        return _rgamma(self, n, shape, rate, scale)

    def rbeta(self, n, shape1, shape2, ncp=None):
        """Random generation for the beta distribution on this stream; see :func:`accudist.rbeta`."""
        return _rbeta(self, n, shape1, shape2, ncp)

    def rlnorm(self, n, meanlog=0.0, sdlog=1.0):
        """Random generation for the log-normal distribution on this stream; see :func:`accudist.rlnorm`."""
        return _rlnorm(self, n, meanlog, sdlog)

    def rchisq(self, n, df, ncp=None):
        """Random generation for the chi-squared distribution on this stream; see :func:`accudist.rchisq`."""
        return _rchisq(self, n, df, ncp)

    def rf(self, n, df1, df2, ncp=None):
        """Random generation for the F distribution on this stream; see :func:`accudist.rf`."""
        return _rf(self, n, df1, df2, ncp)

    def rt(self, n, df, ncp=None):
        """Random generation for the Student t distribution on this stream; see :func:`accudist.rt`."""
        return _rt(self, n, df, ncp)

    def rbinom(self, n, size, prob):
        """Random generation for the binomial distribution on this stream; see :func:`accudist.rbinom`."""
        return _rbinom(self, n, size, prob)

    def rcauchy(self, n, location=0.0, scale=1.0):
        """Random generation for the Cauchy distribution on this stream; see :func:`accudist.rcauchy`."""
        return _rcauchy(self, n, location, scale)

    def rexp(self, n, rate=1.0):
        """Random generation for the exponential distribution on this stream; see :func:`accudist.rexp`."""
        return _rexp(self, n, rate)

    def rgeom(self, n, prob):
        """Random generation for the geometric distribution on this stream; see :func:`accudist.rgeom`."""
        return _rgeom(self, n, prob)

    def rhyper(self, nn, m, n, k):
        """Random generation for the hypergeometric distribution on this stream; see :func:`accudist.rhyper`."""
        return _rhyper(self, nn, m, n, k)

    def rnbinom(self, n, size, prob=None, mu=None):
        """Random generation for the negative binomial distribution on this stream; see :func:`accudist.rnbinom`."""
        return _rnbinom(self, n, size, prob, mu)

    def rpois(self, n, lambda_):
        """Random generation for the Poisson distribution on this stream; see :func:`accudist.rpois`."""
        return _rpois(self, n, lambda_)

    def rweibull(self, n, shape, scale=1.0):
        """Random generation for the Weibull distribution on this stream; see :func:`accudist.rweibull`."""
        return _rweibull(self, n, shape, scale)

    def rlogis(self, n, location=0.0, scale=1.0):
        """Random generation for the logistic distribution on this stream; see :func:`accudist.rlogis`."""
        return _rlogis(self, n, location, scale)

    def rwilcox(self, nn, m, n):
        """Random generation for the Wilcoxon rank sum distribution on this stream; see :func:`accudist.rwilcox`."""
        return _rwilcox(self, nn, m, n)

    def rsignrank(self, nn, n):
        """Random generation for the Wilcoxon signed rank distribution on this stream; see :func:`accudist.rsignrank`."""
        return _rsignrank(self, nn, n)


_default_rng = RNG()


def rnorm(n, mean=0.0, sd=1.0):
    """
    Normal random generation.

    R equivalent: ``rnorm(n, mean = 0, sd = 1)``
    (help page ``?Normal``).

    Parameters
    ----------
    n : int
        Number of draws. Other parameters recycle to this length as in R.
    mean : array_like, optional
        Mean.
    sd : array_like, optional
        Standard deviation.

    Returns
    -------
    ndarray
        ``float64`` array of length ``n``, even for discrete distributions.

    Notes
    -----
    Draws come from standalone Rmath's Marsaglia-MultiCarry generator, so they do
        **not** reproduce R's default (Mersenne-Twister) ``set.seed()`` streams. They do
        reproduce R exactly when R is switched to the same generator:
        ``RNGkind("Marsaglia-Multicarry", "Inversion", "Rejection"); set.seed(s)`` in R
        pairs with ``accudist.set_r_seed(s)`` / ``RNG.from_r_seed(s)`` here.
    """
    return _rnorm(_default_rng, n, mean, sd)


