def rwilcox(nn, m, n):
    """
    Wilcoxon rank sum random generation.

    R equivalent: ``rwilcox(nn, m, n)``
    (help page ``?Wilcoxon``).

    Parameters
    ----------
    nn : int
        Number of draws. Other parameters recycle to this length as in R.
    m : array_like
        Number of observations in the first sample.
    n : array_like
        Number of observations in the second sample.

    Returns
    -------
    ndarray
        ``float64`` array of length ``nn``, even for discrete distributions.

    Notes
    -----
    Draws come from standalone Rmath's Marsaglia-MultiCarry generator, so they do
        **not** reproduce R's default (Mersenne-Twister) ``set.seed()`` streams. They do
        reproduce R exactly when R is switched to the same generator:
        ``RNGkind("Marsaglia-Multicarry", "Inversion", "Rejection"); set.seed(s)`` in R
        pairs with ``accudist.set_r_seed(s)`` / ``RNG.from_r_seed(s)`` here.

    Notes
    -----
    Uses a process-wide distribution table guarded by a lock; concurrent calls
    serialise. Memory grows with the sample sizes; ``accudist.free_caches()`` releases it.
    """
    return _rwilcox(_default_rng, nn, m, n)


